package sources

// DeepSeek Harness adapter — checked against sessions the harness wrote itself
// (test/fixtures/dsh, regenerated by gen.sh: the harness headless against the mock model) and
// against the source of deepseek-harness (packages/session/session-persistence-jsonl/src/format.ts,
// packages/core/session/src/types.ts and known-event-types.ts, packages/llm/llm/src/message.ts
// and types.ts).
//
// Layout: $DSH_HOME/sessions/<encoded cwd>/session-<uuid>/session.v4.jsonl[.zstd]
//
//	(DSH_HOME defaults to ~/.dsh; the directory key is the harness's own encodeSegment of the
//	cwd — never reverse it, the header's cwd is the project).
//
// File format (JSONL, append-only, current generation version 4; physical encoding zstd by
// default, plain .jsonl when compression is "none" — both are standard zstd frames or plain
// text, so readMaybeCompressed handles them and offsets refer to decompressed bytes):
//
//	header line: {"type":"session","version":4,"id","createdAt","cwd","isSeeded","delegationDepth",
//	              "agentPreset"?,"parentSession"?,"origin"?}
//	event lines: {"type","seq","time","data":{…},"surfaceOp"?,"sourceEventSeqs"?}
//
// A subagent child session carries origin "subagent" or delegationDepth > 0 and names its parent
// in parentSession. Older generations (session.v0 … session.v3) are not read: the harness migrates
// them on resume, and their event vocabulary differs.
//
// What counts as the conversation (from the source, confirmed on real sessions):
//   - user/message with source.kind "user" is the user typing; every other source kind
//     (time-context, runtime-context, skill-catalog, agent-instructions, tool-jobs,
//     user-approval, compact-checkpoint, model-selection, …) is context the harness injected.
//   - assistant/message holds the assembled step: text blocks are the reply, reasoning blocks are
//     thinking (dropped), tool-call blocks are the calls. interrupted marks a turn cancelled
//     mid-stream.
//   - tool/call is log-only bookkeeping of the same calls (kept only to name tool/result lines);
//     tool/result is the answer, with isError on the message and an optional error identity.
//   - turn/end closes a turn; reason aborted / interrupted / error is worth a note.
//   - command/run with source.kind "user" is a slash command the user typed.
//   - session/title names the session.
//
// Dropped: system/message and developer/message, agent/inbox/spliced (the claimed messages come
// back as user/message events), compaction, assistant/attempt, and the bookkeeping events
// (approval, permission, sandbox, jobs, hooks, todo, workspace, telemetry, …).
import (
	"encoding/json"
	"fmt"
	"path/filepath"
	"regexp"
	"strconv"
	"strings"
	"time"

	"github.com/veritas501/mem-grep/internal/config"
	"github.com/veritas501/mem-grep/internal/ir"
	"github.com/veritas501/mem-grep/internal/util"
)

// Dsh is the DeepSeek Harness adapter.
type Dsh struct{}

func (Dsh) Kind() ir.SourceKind { return ir.Dsh }

// dshLogName matches one session generation file, compressed or plain.
var dshLogName = regexp.MustCompile(`^session\.v\d+\.jsonl(\.zstd)?$`)

func (Dsh) Discover(cfg *config.Config) []ir.SourceFile {
	var out []ir.SourceFile
	for _, root := range cfg.Dirs(ir.Dsh) {
		root = filepath.Clean(root)
		for _, f := range walkFiles(root, dshLogName.MatchString, 3) {
			head, err := readHead(f.path, 4096)
			if err != nil || !(Dsh{}).Sniff(f.path, head) {
				continue
			}
			sf := ir.SourceFile{Kind: ir.Dsh, Path: f.path, Key: dshKey(f.path), Size: f.size, MtimeMs: f.mtimeMs}
			if id, parent, sub := dshHeaderFlags(head); sub {
				if !cfg.Subagents() {
					continue
				}
				sf.ParentKey = parent
				sf.AgentName = "subagent"
				_ = id
			}
			out = append(out, sf)
		}
	}
	return out
}

// dshKey is the canonical (uncompressed) path, so a session keeps its identity if the harness
// rewrites the file between encodings.
func dshKey(path string) string { return strings.TrimSuffix(path, ".zstd") }

// Sniff reports a DeepSeek Harness session: a `session` header carrying createdAt (omp's header
// has timestamp instead, so the two never collide).
func (Dsh) Sniff(_ string, head []byte) bool {
	var o map[string]any
	if json.Unmarshal(firstLine(head), &o) != nil {
		return false
	}
	_, hasCreated := o["createdAt"]
	return str(o, "type") == "session" && hasCreated
}

// dshHeaderFlags reads subagent markers from a sniffed header. parent is the parent session id.
func dshHeaderFlags(head []byte) (id, parent string, sub bool) {
	var o map[string]any
	if json.Unmarshal(firstLine(head), &o) != nil {
		return "", "", false
	}
	id = str(o, "id")
	parent = str(o, "parentSession")
	depth, _ := o["delegationDepth"].(float64)
	sub = str(o, "origin") == "subagent" || depth > 0 || parent != ""
	return id, parent, sub
}

func (d Dsh) Open(f ir.SourceFile) (*ir.Session, error) {
	buf, err := readMaybeCompressed(f.Path)
	if err != nil {
		return nil, err
	}
	return d.OpenBytes(f, buf, ScanOptions{})
}

// OpenBytes parses a session already read (decompressed). ScanOptions are not used yet.
func (Dsh) OpenBytes(f ir.SourceFile, buf []byte, _ ScanOptions) (*ir.Session, error) {
	read := parseJSONL(buf)
	s := &ir.Session{Kind: ir.Dsh, File: f, CompleteBytes: read.completeBytes, BadLines: read.badLines}
	for _, r := range read.records {
		o := r.obj
		switch str(o, "type") {
		case "session":
			if s.SessionID != "" {
				continue
			}
			s.SessionID = str(o, "id")
			s.Cwd = str(o, "cwd")
			s.StartedAt = dshTime(o["createdAt"])
			if depth, _ := o["delegationDepth"].(float64); str(o, "origin") == "subagent" || depth > 0 || str(o, "parentSession") != "" {
				if s.File.ParentKey == "" {
					s.File.ParentKey = str(o, "parentSession")
				}
				if s.File.AgentName == "" {
					s.File.AgentName = "subagent"
				}
			}
		case "session/title":
			if s.Title == "" {
				if t := strings.TrimSpace(str(obj(o, "data"), "title")); t != "" {
					s.Title = t
				}
			}
		}
	}
	if s.SessionID == "" {
		return nil, nil
	}
	s.Render = func(from, to int64) []ir.Line { return renderDsh(read.records, from, to) }
	return s, nil
}

// renderDsh turns the event log into transcript lines.
func renderDsh(records []record, from, to int64) []ir.Line {
	var lines []ir.Line
	toolNames := map[string]string{}
	for _, r := range records {
		o := r.obj
		emit := r.start >= from && (to < 0 || r.start < to)
		data := obj(o, "data")
		ts := dshTime(o["time"])
		id := dshEntryID(o)
		push := func(role ir.Role, text string, turnStart bool, success *bool) {
			if emit && !util.IsSpaceOnly(text) {
				lines = append(lines, ir.Line{EntryID: id, TS: ts, Role: role, Text: util.Redact(text), TurnStart: turnStart, Start: r.start, End: r.end, Success: success})
			}
		}
		switch str(o, "type") {
		case "user/message":
			if str(obj(data, "source"), "kind") == "user" {
				pushUser(push, dshBlocksText(arr(data["content"])))
			}
		case "assistant/message":
			renderDshAssistant(data, push, toolNames)
		case "tool/call":
			if name := str(data, "name"); name != "" {
				toolNames[str(data, "callId")] = name
			}
		case "tool/result":
			msg := obj(data, "message")
			name := toolNames[str(msg, "toolCallId")]
			text := dshBlocksText(arr(msg["content"]))
			failed := truthy(msg["isError"]) || data["error"] != nil
			// The bash tool reports a failing command as an ordinary result and puts the outcome at
			// the end of its text: "[stderr] … [exit code: N]". A non-zero code is a failure whatever
			// isError says; only shell tools, only the trailing marker (dshExitCode).
			if code, ok := dshExitCode(name, text); ok && code != 0 {
				failed = true
				text = strings.TrimSpace(text) + fmt.Sprintf(" (exit %d)", code)
			}
			pushToolResult(push, name, text, failed)
		case "turn/end":
			renderDshTurnEnd(data, push)
		case "command/run":
			if str(obj(data, "source"), "kind") == "user" {
				cmd := "/" + str(data, "name")
				if args := strings.TrimSpace(str(data, "args")); args != "" {
					cmd += " " + args
				}
				push(ir.RoleNote, "[user ran "+cmd+"]", false, nil)
			}
		}
	}
	return lines
}

// renderDshAssistant renders one assembled assistant message: text, tool calls, and the
// interruption marker. Reasoning blocks are thinking and are dropped.
func renderDshAssistant(data map[string]any, push pushFunc, toolNames map[string]string) {
	msg := obj(data, "message")
	var text []string
	flush := func() {
		pushAssistantText(push, strings.Join(text, "\n"))
		text = nil
	}
	for _, b := range arr(msg["content"]) {
		bm, _ := b.(map[string]any)
		switch str(bm, "type") {
		case "text":
			text = append(text, str(bm, "text"))
		case "reasoning":
			// thinking: dropped, like every other adapter
		case "tool-call":
			flush()
			var args any
			if json.Unmarshal([]byte(str(bm, "arguments")), &args) != nil {
				args = str(bm, "arguments")
			}
			pushToolCall(push, toolNames, str(bm, "id"), str(bm, "name"), args)
		case "image":
			text = append(text, "[image]")
		case "file":
			text = append(text, "[file]")
		}
	}
	flush()
	if truthy(data["interrupted"]) {
		push(ir.RoleNote, "  [assistant turn aborted by the user]", false, nil)
	}
}

// renderDshTurnEnd notes the turns that did not simply complete.
func renderDshTurnEnd(data map[string]any, push pushFunc) {
	reason := obj(data, "reason")
	switch str(reason, "kind") {
	case "aborted", "interrupted":
		push(ir.RoleNote, "  [assistant turn aborted by the user]", false, nil)
	case "error":
		msg := strings.TrimSpace(str(obj(reason, "error"), "message"))
		if msg == "" {
			msg = "unknown"
		}
		push(ir.RoleNote, "  [assistant error: "+util.TruncateMiddle(msg, 300)+"]", false, nil)
	}
}

// dshBlocksText joins the text of content blocks, dropping reasoning.
func dshBlocksText(blocks []any) string {
	var texts []string
	for _, b := range blocks {
		bm, _ := b.(map[string]any)
		switch str(bm, "type") {
		case "text":
			if t := str(bm, "text"); t != "" {
				texts = append(texts, t)
			}
		case "image":
			texts = append(texts, "[image]")
		case "file":
			texts = append(texts, "[file]")
		}
	}
	return strings.Join(texts, "\n")
}

// dshExitCode reads the "[exit code: N]" marker the harness's bash tool appends to its output.
var dshExitCodeRe = regexp.MustCompile(`\[exit code: (-?\d+)\]`)

func dshExitCode(name, text string) (int, bool) {
	// Only shell tools: a grep result that merely quotes the marker stays a success.
	if !shellToolRe.MatchString(name) {
		return 0, false
	}
	all := dshExitCodeRe.FindAllStringSubmatch(text, -1)
	if len(all) == 0 {
		return 0, false
	}
	// The marker must end the report, as the bash tool writes it — not sit mid-output.
	m := all[len(all)-1]
	if !strings.HasSuffix(strings.TrimRight(text, " \t\n"), m[0]) {
		return 0, false
	}
	n, err := strconv.Atoi(m[1])
	return n, err == nil
}

// dshEntryID is the event's sequence number, stable across reads; the header has none.
func dshEntryID(o map[string]any) string {
	seq, ok := o["seq"].(float64)
	if !ok {
		return ""
	}
	return strconv.FormatInt(int64(seq), 10)
}

// dshTime renders a millisecond epoch the way the other adapters render timestamps.
func dshTime(v any) string {
	ms, ok := v.(float64)
	if !ok || ms <= 0 {
		return ""
	}
	return time.UnixMilli(int64(ms)).UTC().Format(time.RFC3339Nano)
}
